-- Goals cell (goals), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA goals;

CREATE FUNCTION goals.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE goals.goals (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    title                    text NOT NULL CHECK (length(title) <= 500 AND length(title) >= 1),
    description              text,
    type                     text CHECK (type IS NULL OR (type IN ('yearly', 'quarterly', 'monthly', 'weekly', 'project'))),
    category                 text CHECK (category IS NULL OR (category IN ('tech', 'business', 'life', 'creative', 'financial', 'health'))),
    status                   text NOT NULL DEFAULT 'planning' CHECK (status IN ('planning', 'active', 'completed', 'abandoned', 'paused')),
    priority                 integer NOT NULL DEFAULT 3,
    start_date               date,
    due_date                 date,
    completed_at             timestamptz,
    progress_percent         integer NOT NULL DEFAULT 0 CHECK (progress_percent >= 0 AND progress_percent <= 100),
    key_results              text,
    notes                    text,
    domain                   text CHECK (domain IS NULL OR (length(domain) <= 200)),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX goals_legacy ON goals.goals (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX goals_category ON goals.goals (workspace_id, category);
CREATE INDEX goals_domain ON goals.goals (workspace_id, domain);
CREATE INDEX goals_priority ON goals.goals (workspace_id, priority);
CREATE INDEX goals_status ON goals.goals (workspace_id, status);
CREATE INDEX goals_type ON goals.goals (workspace_id, type);

CREATE TABLE goals.productivity_goals (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 500 AND length(name) >= 1),
    goal_type                text NOT NULL CHECK (goal_type IN ('daily_completions', 'weekly_completions', 'daily_time', 'weekly_time', 'streak')),
    target_value             double precision NOT NULL,
    current_value            double precision NOT NULL DEFAULT 0,
    period_start             date,
    period_end               date,
    is_active                boolean NOT NULL DEFAULT true,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX productivity_goals_legacy ON goals.productivity_goals (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX productivity_goals_goal_type ON goals.productivity_goals (workspace_id, goal_type);
CREATE INDEX productivity_goals_is_active ON goals.productivity_goals (workspace_id, is_active);

CREATE TABLE goals.goal_tasks (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    goal_id                  bigint,
    title                    text NOT NULL CHECK (length(title) <= 500 AND length(title) >= 1),
    description              text,
    status                   text NOT NULL DEFAULT 'todo' CHECK (status IN ('todo', 'in_progress', 'done', 'blocked')),
    priority                 integer NOT NULL DEFAULT 3,
    due_date                 date,
    completed_at             timestamptz,
    sort_order               integer NOT NULL DEFAULT 0,
    progress_percent         integer NOT NULL DEFAULT 0 CHECK (progress_percent >= 0 AND progress_percent <= 100),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    FOREIGN KEY (workspace_id, goal_id) REFERENCES goals.goals (workspace_id, id)
);
CREATE UNIQUE INDEX goal_tasks_legacy ON goals.goal_tasks (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX goal_tasks_goal_id ON goals.goal_tasks (workspace_id, goal_id);
CREATE INDEX goal_tasks_priority ON goals.goal_tasks (workspace_id, priority);
CREATE INDEX goal_tasks_status ON goals.goal_tasks (workspace_id, status);

CREATE TABLE goals.goal_metrics (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    goal_id                  bigint NOT NULL,
    metric_key               text NOT NULL CHECK (length(metric_key) <= 200 AND length(metric_key) >= 1),
    name                     text NOT NULL CHECK (length(name) <= 500 AND length(name) >= 1),
    description              text,
    metric_type              text NOT NULL DEFAULT 'key_result' CHECK (metric_type IN ('key_result', 'kpi', 'guardrail')),
    direction                text NOT NULL DEFAULT 'increase' CHECK (direction IN ('increase', 'decrease', 'maintain')),
    unit                     text NOT NULL DEFAULT 'count' CHECK (length(unit) <= 60),
    baseline_value           double precision,
    target_value             double precision NOT NULL,
    current_value            double precision,
    status                   text NOT NULL DEFAULT 'no_data' CHECK (status IN ('no_data', 'on_track', 'at_risk', 'off_track', 'achieved')),
    source_type              text NOT NULL DEFAULT 'manual' CHECK (source_type IN ('manual', 'task', 'ai_telemetry', 'system')),
    source_ref               text,
    evidence_ref             text,
    period_start             date,
    period_end               date,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, goal_id, metric_key),
    FOREIGN KEY (workspace_id, goal_id) REFERENCES goals.goals (workspace_id, id)
);
CREATE UNIQUE INDEX goal_metrics_legacy ON goals.goal_metrics (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX goal_metrics_goal_id ON goals.goal_metrics (workspace_id, goal_id);
CREATE INDEX goal_metrics_metric_type ON goals.goal_metrics (workspace_id, metric_type);
CREATE INDEX goal_metrics_status ON goals.goal_metrics (workspace_id, status);

CREATE TABLE goals.goal_portfolio_mappings (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    goal_id                  bigint NOT NULL,
    portfolio_bucket         text NOT NULL CHECK (portfolio_bucket IN ('active_bet', 'infrastructure', 'maintenance', 'capability_backlog', 'option_portfolio', 'large_scale_builder', 'frontier', 'someday_curiosity')),
    attention_class          text NOT NULL CHECK (attention_class IN ('focus', 'parallel', 'background', 'maintenance', 'explore', 'option')),
    attention_cost           integer NOT NULL DEFAULT 0 CHECK (attention_cost >= 0 AND attention_cost <= 5),
    collision_group          text NOT NULL CHECK (length(collision_group) <= 200 AND length(collision_group) >= 1),
    canonical_goal           text NOT NULL CHECK (length(canonical_goal) <= 500 AND length(canonical_goal) >= 1),
    canonical_goal_id        bigint,
    current_season           text NOT NULL CHECK (length(current_season) <= 100 AND length(current_season) >= 1),
    mapping_confidence       text NOT NULL DEFAULT 'provisional' CHECK (mapping_confidence IN ('high', 'provisional', 'review')),
    mapping_source           text NOT NULL DEFAULT 'goal-portfolio-rule-v1' CHECK (length(mapping_source) <= 200),
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, goal_id),
    FOREIGN KEY (workspace_id, goal_id) REFERENCES goals.goals (workspace_id, id),
    FOREIGN KEY (workspace_id, canonical_goal_id) REFERENCES goals.goals (workspace_id, id)
);
CREATE UNIQUE INDEX goal_portfolio_mappings_legacy ON goals.goal_portfolio_mappings (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX goal_portfolio_mappings_attention_class ON goals.goal_portfolio_mappings (workspace_id, attention_class);
CREATE INDEX goal_portfolio_mappings_canonical_goal ON goals.goal_portfolio_mappings (workspace_id, canonical_goal);
CREATE INDEX goal_portfolio_mappings_canonical_goal_id ON goals.goal_portfolio_mappings (workspace_id, canonical_goal_id);
CREATE INDEX goal_portfolio_mappings_collision_group ON goals.goal_portfolio_mappings (workspace_id, collision_group);
CREATE INDEX goal_portfolio_mappings_current_season ON goals.goal_portfolio_mappings (workspace_id, current_season);
CREATE INDEX goal_portfolio_mappings_goal_id ON goals.goal_portfolio_mappings (workspace_id, goal_id);
CREATE INDEX goal_portfolio_mappings_portfolio_bucket ON goals.goal_portfolio_mappings (workspace_id, portfolio_bucket);

CREATE TABLE goals.goal_project_links (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    goal_id                  bigint NOT NULL,
    project_id               bigint NOT NULL,
    relation_type            text NOT NULL DEFAULT 'delivery' CHECK (relation_type IN ('delivery', 'supporting')),
    weight                   double precision NOT NULL DEFAULT 1 CHECK (weight >= 0.0001),
    source                   text NOT NULL DEFAULT 'manual' CHECK (length(source) <= 200),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, goal_id, project_id),
    FOREIGN KEY (workspace_id, goal_id) REFERENCES goals.goals (workspace_id, id)
);
CREATE UNIQUE INDEX goal_project_links_legacy ON goals.goal_project_links (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX goal_project_links_goal_id ON goals.goal_project_links (workspace_id, goal_id);
CREATE INDEX goal_project_links_project_id ON goals.goal_project_links (workspace_id, project_id);
CREATE INDEX goal_project_links_relation_type ON goals.goal_project_links (workspace_id, relation_type);

CREATE TABLE goals.goal_context_links (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    goal_id                  bigint NOT NULL,
    context_id               bigint NOT NULL,
    relation_type            text NOT NULL DEFAULT 'primary' CHECK (relation_type IN ('primary', 'supporting')),
    weight                   double precision NOT NULL DEFAULT 1 CHECK (weight >= 0.0001),
    source                   text NOT NULL DEFAULT 'manual' CHECK (length(source) <= 200),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, goal_id, context_id),
    FOREIGN KEY (workspace_id, goal_id) REFERENCES goals.goals (workspace_id, id)
);
CREATE UNIQUE INDEX goal_context_links_legacy ON goals.goal_context_links (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX goal_context_links_context_id ON goals.goal_context_links (workspace_id, context_id);
CREATE INDEX goal_context_links_goal_id ON goals.goal_context_links (workspace_id, goal_id);
CREATE INDEX goal_context_links_relation_type ON goals.goal_context_links (workspace_id, relation_type);

CREATE TABLE goals.goal_task_project_links (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    goal_task_id             bigint NOT NULL,
    project_id               bigint NOT NULL,
    relation_type            text NOT NULL DEFAULT 'delivery' CHECK (relation_type IN ('delivery', 'supporting')),
    weight                   double precision NOT NULL DEFAULT 1 CHECK (weight >= 0.0001),
    source                   text NOT NULL DEFAULT 'manual' CHECK (length(source) <= 200),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, goal_task_id, project_id),
    FOREIGN KEY (workspace_id, goal_task_id) REFERENCES goals.goal_tasks (workspace_id, id)
);
CREATE UNIQUE INDEX goal_task_project_links_legacy ON goals.goal_task_project_links (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX goal_task_project_links_goal_task_id ON goals.goal_task_project_links (workspace_id, goal_task_id);
CREATE INDEX goal_task_project_links_project_id ON goals.goal_task_project_links (workspace_id, project_id);
CREATE INDEX goal_task_project_links_relation_type ON goals.goal_task_project_links (workspace_id, relation_type);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE goals.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('goal', 'goal-task', 'goal-metric', 'goal-portfolio-mapping', 'productivity-goal', 'goal-project-link', 'goal-context-link', 'goal-task-project-link')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE goals.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON goals.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['goals', 'productivity_goals', 'goal_tasks', 'goal_metrics', 'goal_portfolio_mappings', 'goal_project_links', 'goal_context_links', 'goal_task_project_links', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE goals.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE goals.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON goals.%I'
                       ' USING (workspace_id = goals.current_workspace())'
                       ' WITH CHECK (workspace_id = goals.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA goals TO goals_api;
GRANT EXECUTE ON FUNCTION goals.current_workspace() TO goals_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON goals.goals, goals.productivity_goals, goals.goal_tasks, goals.goal_metrics, goals.goal_portfolio_mappings, goals.goal_project_links, goals.goal_context_links, goals.goal_task_project_links TO goals_api;
GRANT USAGE ON SEQUENCE goals.goals_id_seq, goals.productivity_goals_id_seq, goals.goal_tasks_id_seq, goals.goal_metrics_id_seq, goals.goal_portfolio_mappings_id_seq, goals.goal_project_links_id_seq, goals.goal_context_links_id_seq, goals.goal_task_project_links_id_seq TO goals_api;
GRANT SELECT, INSERT ON goals.create_keys TO goals_api;
GRANT SELECT, INSERT ON goals.outbox TO goals_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON goals.outbox TO goals_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON goals.outbox TO goals_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA goals TO goals_publisher;
GRANT SELECT ON goals.outbox TO goals_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON goals.outbox TO goals_publisher;
